{"command":"python3 - << 'PY'
import subprocess, os, tempfile, pathlib, shutil, gzip, zlib, struct, time, sys
EXE=os.path.abspath("./executable")
def run(args, inp=b"", cwd=None, env=None, exe=EXE):
    e=dict(os.environ)
    if env: e.update(env)
    # clear GZIP/PIGZ unless specified
    for k in ("GZIP","PIGZ"):
        if env is None or k not in env: e.pop(k,None)
    return subprocess.run([exe]+args, capture_output=True, input=inp, cwd=cwd, env=e)

# argv0 tests
tmp=tempfile.mkdtemp()
for name in ["pigz","unpigz","gzip","gunzip","pigzcat","zcat","foo","PIGZ"]:
    link=os.path.join(tmp,name)
    os.symlink(EXE, link)
    r=subprocess.run([link,"-V"], capture_output=True)
    r2=subprocess.run([link], capture_output=True, input=b"hi "+name.encode())
    # decompress attempt if unpigz-like: input plain should fail
    print(name, "V:", r.stdout, r.stderr[:100], r.returncode, "plain-in outlen", len(r2.stdout), "err", r2.stderr[:200], r2.returncode)
    if r2.stdout.startswith(b'\x1f\x8b'):
        print("  compressed")
print("tmp",tmp)
# Help prog name changes?
for name in ["pigz","unpigz","gzip"]:
    link=os.path.join(tmp,name)
    r=subprocess.run([link,"-h"], capture_output=True)
    print(name, "help first line", r.stderr.split(b"\n")[0])
    r=subprocess.run([link,"-x"], capture_output=True)
    print(name, "bad opt", r.stderr)
PY"}

