import sys; sys.path.insert(0,"/tmp/probe")
from probe import *

def make_gz(tmp, name="file.txt", content=b"hello world\n"*5):
    open(os.path.join(tmp,name),"wb").write(content)
    r=run(["-k",name],cwd=tmp) # produces .gz (?) keep
    # Actually -k with file? check
    print("make",r.returncode,r.stderr, os.listdir(tmp))

def t(args, files):
    tmp=tempfile.mkdtemp()
    for n,c in files.items():
        mode="wb"
        open(os.path.join(tmp,n),mode).write(c)
    r=run(args,cwd=tmp)
    print(args,"rc",r.returncode,"err",r.stderr,"out",r.stdout[:80],"files",sorted(os.listdir(tmp)))
    for f in sorted(os.listdir(tmp)):
        p=os.path.join(tmp,f)
        if os.path.isfile(p):
            print(" ",f, open(p,"rb").read()[:80])
    return tmp

