{"command":"python3 - << 'PY'
import sys; sys.path.insert(0,"/tmp/probe")
from probe import *
import zlib
def pigz(data, args):
    r=run(args, inp=data)
    return r.stdout
def raw_zlib(data, level, strategy=0, mem=8):
    c=zlib.compressobj(level, zlib.DEFLATED, -15, mem, strategy)
    # pigz uses Z_SYNC_FLUSH per block then (?) final?
    out=c.compress(data)+c.flush(zlib.Z_SYNC_FLUSH)
    # remove 4 bytes sync flush marker? pigz: last block? Look
    return out
data=b"hello world hello world\n"*100
for level in range(0,10):
    out=pigz(data, [f"-{level}","-p1"])
    # strip gzip hdr 10 + trailer 8
    deflate=out[10:-8]
    for strategy in [0,1,2,3,4]: # FILTERED=1, HUFFMAN=2, RLE=3, FIXED=4
        for flushmode in ["sync_then_finish","finish","sync_strip"]:
            c=zlib.compressobj(level, zlib.DEFLATED, -15, 8, strategy)
            if flushmode=="finish":
                cand=c.compress(data)+c.flush()
            elif flushmode=="sync_then_finish":
                cand=c.compress(data)+c.flush(zlib.Z_SYNC_FLUSH)+c.flush()
            else:
                cand=c.compress(data)+c.flush(zlib.Z_SYNC_FLUSH)
                cand=cand[:-4] if cand.endswith(b"\x00\x00\xff\xff") else cand
            if cand==deflate:
                print(level, "match strategy",strategy, flushmode)
    # print sizes
    print(level, "pigz deflate len", len(deflate), deflate[:20])
PY"}

