import sys; sys.path.insert(0,"/tmp/probe")
from probe import *
import gzip, zlib, zipfile, io
def show(data,args=["-lv"]):
    r=run(args,inp=data)
    print(repr(r.stdout.decode()))
    for line in r.stdout.decode().splitlines(True):
        print([i for i,ch in enumerate(line)], line)
        # print indexes ruler
        print(''.join(str(i%10) for i in range(len(line))))
        print(line)
def make(method):
    if method=="gzip": return gzip.compress(b"hello world\n"*100,mtime=0)
    if method=="gzip_named":
        # pigz compress named
        pass
    if method=="zlib": return zlib.compress(b"hello world\n"*100)
    if method=="zip":
        buf=io.BytesIO()
        with zipfile.ZipFile(buf,"w",compression=zipfile.ZIP_DEFLATED) as z: z.writestr("a.txt",b"hello world\n"*100)
        return buf.getvalue()
for m in ["gzip","zlib","zip"]:
    show(make(m))
    show(make(m),["-l"])
# timestamp variations: gzip with mtime specific
import struct
def gz_mtime(mt):
    d=bytearray(gzip.compress(b"abc",mtime=0)); d[4:8]=struct.pack("<I",mt); return bytes(d)
for mt in [0,1,1234567890, 2147483647, 4294967295]:
    show(gz_mtime(mt))
# zip timestamps DOS conversions?
# empty gzip percentage
show(gzip.compress(b"",mtime=0))
show(zlib.compress(b""))
PY"}

