import pty, os, subprocess, select
EXE=os.path.abspath("./executable")
def run_combo(args, stdin_tty=False, stdout_tty=False):
    m_out=s_out=None; m_in=s_in=None
    if stdout_tty: m_out,s_out=pty.openpty()
    if stdin_tty: m_in,s_in=pty.openpty()
    p=subprocess.Popen([EXE]+args, stdin=s_in if stdin_tty else subprocess.PIPE, stdout=s_out if stdout_tty else subprocess.PIPE, stderr=s_out if stdout_tty else subprocess.PIPE)
    for fd in (s_in,s_out):
        if fd is not None: os.close(fd)
    out=b""; err=b""
    if not stdin_tty:
        p.stdin.write(b"hi\n"); p.stdin.close()
    else:
        # close master to give EOF/HUP?
        pass
    if stdout_tty:
        p.wait(timeout=3)
        while True:
            r,_,_=select.select([m_out],[],[],0.2)
            if not r: break
            try:
                d=os.read(m_out,4096)
            except OSError: break
            if not d: break
            out+=d
    else:
        out,err=p.communicate.__self__ if False else (p.stdout.read(), p.stderr.read()); p.wait()
    if m_out: os.close(m_out)
    if m_in: os.close(m_in)
    return p.returncode,out,err
for stdin_tty in [False,True]:
    for stdout_tty in [False,True]:
        for args in [[],["-c"],["-v"]]:
            try:
                rc,out,err=run_combo(args,stdin_tty,stdout_tty)
                print(f"stdin_tty={stdin_tty} stdout_tty={stdout_tty} args={args} rc={rc} out={out[:80]!r} err={err[:80]!r}")
            except Exception as e:
                print("err combo",stdin_tty,stdout_tty,args,e)
