import sys; sys.path.insert(0,"/tmp/probe")
from probe import *
import zlib
def get_deflate(data,args):
    r=run(args,inp=data); return r.stdout[10:-8], r.stdout
# Compare strategies on data with repeats & runs
datasets={
 "runs": b"aaaaaaaaaaaaaaaaaaaaaaaaaaaaabbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbcccccccccccc",
 "repeats": b"abcabcabcabcabcabcabcabc"*100,
 "randomlike": bytes(range(256))*20,
 "text": b"hello world, hello pigz world! "*500,
}
for name,data in datasets.items():
    print(name)
    for args in [[],["-H"],["-U"],["-H","-1"],["-U","-1"],["-H","-9"],["-U","-9"],["-F"]]:
        d,out=get_deflate(data,args)
        # compare zlib strategies
        matches=[]
        lvl=int([a for a in args if a.startswith("-") and len(a)==2 and a[1].isdigit()][0][1]) if any(len(a)==2 and a[1].isdigit() for a in args) else 6
        for strat,sname in [(0,"default"),(1,"filtered"),(2,"huffman"),(3,"rle"),(4,"fixed")]:
            c=zlib.compressobj(lvl,zlib.DEFLATED,-15,8,strat)
            cand=c.compress(data)+c.flush()
            if cand==d: matches.append(sname)
        print(args, len(d), matches)
