import random,zlib
random.seed(5); data=bytes(random.getrandbits(8) for _ in range(50000))
ends=[194,235,1958,3016,10282,10566,14094,21357,28366,29303,38123,41658,45008]
funcs={
 "crc":lambda b:zlib.crc32(b), "adler":lambda b:zlib.adler32(b),
 "fnv1a":lambda b: __import__('functools').reduce(lambda h,x: ((h ^ x)*16777619)&0xffffffff,b,2166136261),
 "fnv1":lambda b: __import__('functools').reduce(lambda h,x: ((h*16777619)&0xffffffff) ^ x,b,2166136261),
 "djb":lambda b: __import__('functools').reduce(lambda h,x: ((h*33)+x)&0xffffffff,b,5381),
 "djb xor":lambda b: __import__('functools').reduce(lambda h,x: ((h*33)^x)&0xffffffff,b,5381),
 "sdbm":lambda b: __import__('functools').reduce(lambda h,x: (x + (h<<6)+(h<<16)-h)&0xffffffff,b,0),
 "java31":lambda b: __import__('functools').reduce(lambda h,x: ((h*31)+x)&0xffffffff,b,0),
}
for W in [4,8,12,16,24,32,48,64,96,128,256,512,1024]:
    if any(p<W for p in ends): continue
    for name,f in funcs.items():
        vals=[f(data[p-W:p]) for p in ends]
        for k in range(8,21):
            if len(set(v&((1<<k)-1) for v in vals))==1:
                print("found",name,W,k,set(v&((1<<k)-1) for v in vals))
print("done")
