from probe import *
import zlib, struct
def manual(name=None):
    content=b"hello world"*20
    flg=8 if name else 0
    hdr=b'\x1f\x8b\x08'+bytes([flg])+b'\x00\x00\x00\x00\x00\x03'
    if name: hdr+=name+b'\x00'
    c=zlib.compressobj(6,zlib.DEFLATED,-15); body=c.compress(content)+c.flush(); return hdr+body+struct.pack("<II",zlib.crc32(content),len(content)), len(hdr)
for name in [None,b"a",b"longfilename.txt"]:
    data,head=manual(name)
    print("name",name,"head",head,"full",len(data))
    for l in range(head, head+15):
        r=run(["-l"],inp=data[:l]); print(l, r.returncode, r.stdout, r.stderr)
