{"command":"cat > pigz.c << 'EOF'
/*
 * A parallel-style gzip/zlib/zip compressor and decompressor.
 * Written from scratch as a clean-room implementation of the documented
 * pigz command-line behaviour.  Uses zlib for DEFLATE compression and
 * decompression; output data is split into blocks which are compressed
 * with the previous input as a dictionary, mirroring the interface and
 * output conventions of the reference tool.
 */
#define _POSIX_C_SOURCE 200809L
#define _DEFAULT_SOURCE 1
#include <ctype.h>
#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <math.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>
#include <zlib.h>

#define FORMAT_GZIP 0
#define FORMAT_ZLIB 1
#define FORMAT_ZIP  2

#define PROC_DELETE 0
#define PROC_KEEP   1
#define PROC_FAIL   2

static const char help_text[] =
    "Usage: pigz [options] [files ...]\n"
    "  will compress files in place, adding the suffix '.gz'. If no files are\n"
    "  specified, stdin will be compressed to stdout. pigz does what gzip does,\n"
    "  but spreads the work over multiple processors and cores when compressing.\n"
    "\n"
    "Options:\n"
    "  -0 to -9, -11        Compression level (level 11, zopfli, is much slower)\n"
    "  --fast, --best       Compression levels 1 and 9 respectively\n"
    "  -A, --alias xxx      Use xxx as the name for any --zip entry from stdin\n"
    "  -b, --blocksize mmm  Set compression block size to mmmK (default 128K)\n"
    "  -c, --stdout         Write all processed output to stdout (won't delete)\n"
    "  -C, --comment ccc    Put comment ccc in the gzip or zip header\n"
    "  -d, --decompress     Decompress the compressed input\n"
    "  -f, --force          Force overwrite, compress .gz, links, and to terminal\n"
    "  -F  --first          Do iterations first, before block split for -11\n"
    "  -h, --help           Display a help screen and quit\n"
    "  -H, --huffman        Use only Huffman coding for compression\n"
    "  -i, --independent    Compress blocks independently for damage recovery\n"
    "  -I, --iterations n   Number of iterations for -11 optimization\n"
    "  -J, --maxsplits n    Maximum number of split blocks for -11\n"
    "  -k, --keep           Do not delete original file after processing\n"
    "  -K, --zip            Compress to PKWare zip (.zip) single entry format\n"
    "  -l, --list           List the contents of the compressed input\n"
    "  -L, --license        Display the pigz license and quit\n"
    "  -m, --no-time        Do not store or restore mod time\n"
    "  -M, --time           Store or restore mod time\n"
    "  -n, --no-name        Do not store or restore file name or mod time\n"
    "  -N, --name           Store or restore file name and mod time\n"
    "  -O  --oneblock       Do not split into smaller blocks for -11\n"
    "  -p, --processes n    Allow up to n compression threads (default is the\n"
    "                       number of online processors, or 8 if unknown)\n"
    "  -q, --quiet          Print no messages, even on error\n"
    "  -r, --recursive      Process the contents of all subdirectories\n"
    "  -R, --rsyncable      Input-determined block locations for rsync\n"
    "  -S, --suffix .sss    Use suffix .sss instead of .gz (for compression)\n"
    "  -t, --test           Test the integrity of the compressed input\n"
    "  -U, --rle            Use run-length encoding for compression\n"
    "  -v, --verbose        Provide more verbose output\n"
    "  -V  --version        Show the version of pigz\n"
    "  -Y  --synchronous    Force output file write to permanent storage\n"
    "  -z, --zlib           Compress to zlib (.zz) instead of gzip format\n"
    "  --                   All arguments after \"--\" are treated as files\n";

static const char version_text[] = "pigz 2.8\n";
static const char license_text[] =
    "pigz 2.8\n"
    "Copyright (C) 2007-2023 Mark Adler\n"
    "Subject to the terms of the zlib license.\n"
    "No warranty is provided or implied.\n";

struct file_entry {
    char *name;      /* NULL means stdin */
    int is_stdin;
};

static struct {
    const char *prog;
    int ret;
    int verbosity;               /* -1 quiet, 0 normal, >0 verbose */
    int level;                   /* 0..9, 11 */
    int format;
    int decode;
    int test;
    int list;
    int to_stdout;
    int keep;
    int force;
    int independent;
    int rsyncable;
    int recursive;
    int synchronous;
    int strategy;
    int name_state;              /* -1 unset, 0 off, 1 on */
    int time_state;              /* -1 unset, 0 off, 1 on */
    char *suffix;
    char *alias;                 /* NULL if not set */
    char *comment;               /* NULL if not set */
    unsigned long block_kb;
    unsigned long processes;
    long iterations;
    long maxsplits;
    int first;
    int oneblock;
    int main_argc;
    struct file_entry *files;
    size_t nfiles;
    size_t files_cap;
    char *out_unlink;            /* output file to remove on abort */
    int verbose_started;
    int list_header_done;
} g;

/* ---------- small utilities ---------- */

static void *xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (p == NULL) {
        if (g.verbosity >= 0)
            fprintf(stderr, "%s: abort: out of memory\n", g.prog);
        exit(ENOMEM);
    }
    return p;
}

static void *xrealloc(void *old, size_t n)
{
    void *p = realloc(old, n ? n : 1);
    if (p == NULL) {
        if (g.verbosity >= 0)
            fprintf(stderr, "%s: abort: out of memory\n", g.prog);
        exit(ENOMEM);
    }
    return p;
}

static char *xstrdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = xmalloc(n);
    memcpy(p, s, n);
    return p;
}

static char *xstrndup(const char *s, size_t n)
{
    char *p = xmalloc(n + 1);
    memcpy(p, s, n);
    p[n] = '\0';
    return p;
}

static void set_str(char **dst, const char *src)
{
    free(*dst);
    *dst = xstrdup(src);
}

static const char *base_name(const char *path)
{
    const char *slash = strrchr(path, '/');
    return slash ? slash + 1 : path;
}

static int ends_with(const char *s, const char *suff)
{
    size_t ls = strlen(s), lf = strlen(suff);
    return ls >= lf && memcmp(s + ls - lf, suff, lf) == 0;
}

typedef struct {
    unsigned char *data;
    size_t len;
    size_t cap;
} Buffer;

static void buf_init(Buffer *b)
{
    b->data = NULL;
    b->len = 0;
    b->cap = 0;
}

static void buf_free(Buffer *b)
{
    free(b->data);
    b->data = NULL;
    b->len = b->cap = 0;
}

static void buf_reserve(Buffer *b, size_t need)
{
    if (need > b->cap) {
        size_t cap = b->cap ? b->cap : 256;
        while (cap < need)
            cap *= 2;
        b->data = xrealloc(b->data, cap);
        b->cap = cap;
    }
}

static void buf_append(Buffer *b, const unsigned char *p, size_t n)
{
    if (n == 0)
        return;
    buf_reserve(b, b->len + n);
    memcpy(b->data + b->len, p, n);
    b->len += n;
}

static void buf_append_byte(Buffer *b, unsigned char c)
{
    buf_append(b, &c, 1);
}

static void buf_append_str(Buffer *b, const char *s)
{
    buf_append(b, (const unsigned char *)s, strlen(s));
}

/* ---------- diagnostics ---------- */

static void print_abort(int code, const char *fmt, va_list ap)
{
    if (g.verbosity >= 0) {
        fprintf(stderr, "%s: abort: ", g.prog);
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
        fflush(stderr);
    }
    if (g.out_unlink != NULL) {
        unlink(g.out_unlink);
    }
    exit(code);
}

static void abort_msg(int code, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    print_abort(code, fmt, ap);
    va_end(ap);
}

static void abort_read(const char *name)
{
    int e = errno ? errno : EIO;
    abort_msg(e, "read error on %s (%s)", name, strerror(e));
}

static void abort_read_e(const char *name, int e)
{
    abort_msg(e, "read error on %s (%s)", name, strerror(e));
}

static void abort_write(const char *name)
{
    int e = errno ? errno : EIO;
    abort_msg(e, "write error on %s (%s)", name, strerror(e));
}

static void abort_write_e(const char *name, int e)
{
    abort_msg(e, "write error on %s (%s)", name, strerror(e));
}

/* Generic "prog: ..." note; always sets the exit status to 1. */
static void note_msg(const char *fmt, ...)
{
    if (g.verbosity >= 0) {
        va_list ap;
        va_start(ap, fmt);
        fprintf(stderr, "%s: ", g.prog);
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
        va_end(ap);
    }
    g.ret = 1;
}

static void warn_msg(const char *fmt, ...)
{
    if (g.verbosity >= 0) {
        va_list ap;
        va_start(ap, fmt);
        fprintf(stderr, "%s: warning: ", g.prog);
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
        va_end(ap);
    }
    g.ret = 1;
}

/* Format for the common skipping notice.  suppressed is handled by callers
 * when checking g.verbosity. */
static void skip_msg_v(const char *fmt, va_list ap)
{
    if (g.verbosity >= 0) {
        fprintf(stderr, "%s: skipping: ", g.prog);
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
    }
    g.ret = 1;
}

static int skip_msg(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    skip_msg_v(fmt, ap);
    va_end(ap);
    return 1;
}

/* Same text but does not set the exit status (used for suffix notices). */
static int skip_msg_quiet_ret(const char *fmt, ...)
{
    if (g.verbosity >= 0) {
        va_list ap;
        va_start(ap, fmt);
        fprintf(stderr, "%s: skipping: ", g.prog);
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
        va_end(ap);
    }
    return 0;
}

static void start_verbose(const char *in_name, const char *out_name)
{
    if (g.verbosity > 0 && !g.verbose_started) {
        fprintf(stderr, "%s to %s ", in_name, out_name);
        fflush(stderr);
        g.verbose_started = 1;
    }
}

static void finish_verbose(void)
{
    if (g.verbose_started) {
        if (g.verbosity > 0)
            fputc('\n', stderr);
        fflush(stderr);
        g.verbose_started = 0;
    }
}

static void do_help(void)
{
    if (g.verbosity < 0)
        return;
    fputs(help_text, stderr);
    exit(0);
}

static void do_version(void)
{
    fputs(version_text, stdout);
    if (g.verbosity > 0)
        printf("zlib %s\n", zlibVersion());
    exit(0);
}

static void do_license(void)
{
    fputs(license_text, stdout);
    exit(0);
}
EOF
cat pigz.c | wc -l"}

