        if (p32 < 1)
            abort_msg(EINVAL, "invalid number of processes: %s", s);
        if (v > 1073741823UL && v != 2147483647UL)
            abort_msg(EINVAL, "too many processes: %s", s);
        g.processes = v;
        break;
    }
