/* Fetch the parameter for an option, either attached or the next token. */
static const char *get_parameter(struct opt_source *src, const char *arg,
                                 size_t pos, char opt, int *consumed_rest)
{
    const char *rest = arg + pos;
    *consumed_rest = 0;
    if (rest[0] != '\0') {
        /* -S and -C require a following separate token. */
        if (opt == 'S' || opt == 'C')
            abort_msg(EINVAL, "invalid usage: -%c must be followed by space", opt);
        *consumed_rest = 1;
        return rest;
    }
    if (src->index + 1 >= src->argc || src->argv[src->index + 1][0] == '-')
        abort_msg(EINVAL, "missing parameter after -%c", opt);
    src->index++;
    return src->argv[src->index];
}

static int is_param_opt(char c)
{
    return c == 'b' || c == 'p' || c == 'S' || c == 'A' || c == 'C' ||
           c == 'I' || c == 'J';
}

static void set_format(int format)
{
    g.format = format;
    if (format == FORMAT_ZLIB)
        set_str(&g.suffix, ".zz");
    else if (format == FORMAT_ZIP)
        set_str(&g.suffix, ".zip");
}

static void file_token(struct opt_source *src, const char *arg)
{
    if (src->is_env)
        abort_msg(EINVAL, "cannot provide files in %s environment variable",
                  src->env_name);
    add_file(arg, 0);
}

/* Process a single short-option token (which may be bundled). */
static void parse_short(struct opt_source *src, const char *arg)
{
    size_t i = 1;
    while (arg[i] != '\0') {
        unsigned char c = (unsigned char)arg[i];
        if (isdigit(c)) {
            unsigned long value = 0;
            while (isdigit((unsigned char)arg[i])) {
                if (value < 1000)
                    value = value * 10 + (unsigned long)(arg[i] - '0');
                i++;
            }
            if (!((value <= 9) || value == 11))
                abort_msg(EINVAL, "only levels 0..9 and 11 are allowed");
            g.level = (int)value;
            continue;
        }
        i++;
        switch (c) {
        case 'h': do_help(); break;
        case 'L': do_license(); break;
        case 'V': do_version(); break;
        case 'q': g.verbosity = -1; break;
        case 'v': g.verbosity++; break;
        case 'c': g.to_stdout = 1; break;
        case 'd': g.decode = 1; break;
        case 't': g.test = 1; break;
        case 'l': g.list = 1; break;
        case 'f': g.force = 1; break;
        case 'k': g.keep = 1; break;
        case 'i': g.independent = 1; break;
        case 'r': g.recursive = 1; break;
        case 'R': g.rsyncable = 1; break;
        case 'Y': g.synchronous = 1; break;
        case 'z': set_format(FORMAT_ZLIB); break;
        case 'K': set_format(FORMAT_ZIP); break;
        case 'H': g.strategy = Z_HUFFMAN_ONLY; break;
        case 'U': g.strategy = Z_RLE; break;
        case 'F': g.first = 1; break;
        case 'O': g.oneblock = 1; break;
        case 'n': g.name_state = 0; g.time_state = 0; break;
        case 'N': g.name_state = 1; g.time_state = 1; break;
        case 'm': g.time_state = 0; break;
        case 'M': g.time_state = 1; break;
        case '0': case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8': case '9':
            /* handled above by the digit branch (unreachable) */
            break;
        default:
            if (is_param_opt((char)c)) {
                int consumed = 0;
                const char *param =
                    get_parameter(src, arg, i, (char)c, &consumed);
                apply_param_option((char)c, param);
                return;
            }
            abort_msg(EINVAL, "invalid option: -%c", c);
            break;
        }
    }
}

struct long_opt {
    const char *name;
    char param;       /* parameter option letter, or 0 */
    int action;
};

enum {
    ACT_NONE, ACT_FAST, ACT_BEST, ACT_STDOUT, ACT_DECOMPRESS, ACT_FORCE,
    ACT_FIRST, ACT_HELP, ACT_HUFFMAN, ACT_INDEPENDENT, ACT_KEEP, ACT_ZIP,
    ACT_LIST, ACT_LICENSE, ACT_NO_TIME, ACT_TIME, ACT_NO_NAME, ACT_NAME,
    ACT_ONEBLOCK, ACT_QUIET, ACT_RECURSIVE, ACT_RSYNCABLE, ACT_TEST,
    ACT_RLE, ACT_VERBOSE, ACT_VERSION, ACT_SYNCHRONOUS, ACT_ZLIB
};

static const struct long_opt long_opts[] = {
    {"fast", 0, ACT_FAST}, {"best", 0, ACT_BEST},
    {"alias", 'A', 0}, {"blocksize", 'b', 0},
    {"stdout", 0, ACT_STDOUT}, {"to-stdout", 0, ACT_STDOUT},
    {"comment", 'C', 0},
    {"decompress", 0, ACT_DECOMPRESS}, {"uncompress", 0, ACT_DECOMPRESS},
    {"force", 0, ACT_FORCE}, {"first", 0, ACT_FIRST},
    {"help", 0, ACT_HELP}, {"huffman", 0, ACT_HUFFMAN},
    {"independent", 0, ACT_INDEPENDENT},
    {"iterations", 'I', 0}, {"maxsplits", 'J', 0},
    {"keep", 0, ACT_KEEP}, {"zip", 0, ACT_ZIP},
    {"list", 0, ACT_LIST}, {"license", 0, ACT_LICENSE},
    {"no-time", 0, ACT_NO_TIME}, {"time", 0, ACT_TIME},
    {"no-name", 0, ACT_NO_NAME}, {"name", 0, ACT_NAME},
    {"oneblock", 0, ACT_ONEBLOCK}, {"processes", 'p', 0},
    {"quiet", 0, ACT_QUIET}, {"silent", 0, ACT_QUIET},
    {"recursive", 0, ACT_RECURSIVE}, {"rsyncable", 0, ACT_RSYNCABLE},
    {"suffix", 'S', 0}, {"test", 0, ACT_TEST},
    {"rle", 0, ACT_RLE}, {"verbose", 0, ACT_VERBOSE},
    {"version", 0, ACT_VERSION}, {"synchronous", 0, ACT_SYNCHRONOUS},
    {"zlib", 0, ACT_ZLIB},
    {NULL, 0, 0}
};

static void parse_long(struct opt_source *src, const char *arg)
{
    const struct long_opt *lo;
    for (lo = long_opts; lo->name != NULL; lo++) {
        if (strcmp(arg + 2, lo->name) == 0)
            break;
    }
    if (lo->name == NULL)
        abort_msg(EINVAL, "invalid option: %s", arg);
    if (lo->param != 0) {
        const char *param;
        if (src->index + 1 >= src->argc || src->argv[src->index + 1][0] == '-')
            abort_msg(EINVAL, "missing parameter after -%c", lo->param);
        src->index++;
        param = src->argv[src->index];
        apply_param_option(lo->param, param);
        return;
    }
    switch (lo->action) {
    case ACT_FAST: g.level = 1; break;
    case ACT_BEST: g.level = 9; break;
    case ACT_STDOUT: g.to_stdout = 1; break;
    case ACT_DECOMPRESS: g.decode = 1; break;
    case ACT_FORCE: g.force = 1; break;
    case ACT_FIRST: g.first = 1; break;
    case ACT_HELP: do_help(); break;
    case ACT_HUFFMAN: g.strategy = Z_HUFFMAN_ONLY; break;
    case ACT_INDEPENDENT: g.independent = 1; break;
    case ACT_KEEP: g.keep = 1; break;
    case ACT_ZIP: set_format(FORMAT_ZIP); break;
    case ACT_LIST: g.list = 1; break;
    case ACT_LICENSE: do_license(); break;
    case ACT_NO_TIME: g.time_state = 0; break;
    case ACT_TIME: g.time_state = 1; break;
    case ACT_NO_NAME: g.name_state = 0; g.time_state = 0; break;
    case ACT_NAME: g.name_state = 1; g.time_state = 1; break;
    case ACT_ONEBLOCK: g.oneblock = 1; break;
    case ACT_QUIET: g.verbosity = -1; break;
    case ACT_RECURSIVE: g.recursive = 1; break;
    case ACT_RSYNCABLE: g.rsyncable = 1; break;
    case ACT_TEST: g.test = 1; break;
    case ACT_RLE: g.strategy = Z_RLE; break;
    case ACT_VERBOSE: g.verbosity++; break;
    case ACT_VERSION: do_version(); break;
    case ACT_SYNCHRONOUS: g.synchronous = 1; break;
    case ACT_ZLIB: set_format(FORMAT_ZLIB); break;
    default: break;
    }
}

static void parse_token(struct opt_source *src, const char *arg)
{
    if (!src->is_env && src->after_dd) {
        add_file(arg, 0);
        return;
    }
    if (!src->is_env && strcmp(arg, "--") == 0) {
        src->after_dd = 1;
        return;
    }
    if (arg[0] != '-' || arg[1] == '\0') {
        if (src->is_env) {
            /* A bare "-" or a plain word in an environment value. */
            if (!(arg[0] == '-' && arg[1] == '\0'))
                file_token(src, arg);
            else
                file_token(src, arg);
        } else if (strcmp(arg, "-") == 0) {
            add_file(NULL, 1);
        } else {
            add_file(arg, 0);
        }
        return;
    }
    if (arg[1] == '-')
        parse_long(src, arg);
    else
        parse_short(src, arg);
}

static void parse_source(char **argv, int argc, int is_env, const char *env_name)
{
    struct opt_source src;
    src.argv = argv;
    src.argc = argc;
    src.is_env = is_env;
    src.env_name = env_name;
    src.after_dd = 0;
    for (src.index = 0; src.index < argc; src.index++) {
        /* In environment mode "--" is not a separator. */
        if (is_env && strcmp(argv[src.index], "--") == 0)
            abort_msg(EINVAL, "invalid option: --");
        parse_token(&src, argv[src.index]);
    }
}

static void parse_environment(const char *env_name)
{
    const char *value = getenv(env_name);
    char *copy;
    char **tokens = NULL;
    size_t ntok = 0, cap = 0;
    const char *s;
    size_t len, trailing, k;

    if (value == NULL || value[0] == '\0')
        return;
    copy = xstrdup(value);
    /* Skip leading separators (spaces and tabs only). */
    s = copy;
    while (*s == ' ' || *s == '\t')
        s++;
    if (*s == '\0') {
        /* A value consisting solely of separators behaves like one
         * empty file token. */
        tokens = xmalloc(sizeof(char *));
        tokens[0] = (char *)"";
        ntok = 1;
    } else {
        /* Split on runs of spaces/tabs. */
        char *p = (char *)s;
        while (*p) {
            while (*p == ' ' || *p == '\t')
                p++;
            if (*p == '\0')
                break;
            if (ntok == cap) {
                cap = cap ? cap * 2 : 8;
                tokens = xrealloc(tokens, cap * sizeof(char *));
            }
            tokens[ntok++] = p;
            while (*p && *p != ' ' && *p != '\t')
                p++;
            if (*p) {
                *p = '\0';
                p++;
            }
        }
        /* Two or more separators at the very end add an empty token. */
        len = strlen(value);
        trailing = 0;
        for (k = len; k > 0 && (value[k - 1] == ' ' || value[k - 1] == '\t'); k--)
            trailing++;
        if (trailing >= 2) {
            if (ntok == cap) {
                cap = cap ? cap * 2 : 8;
                tokens = xrealloc(tokens, cap * sizeof(char *));
            }
            tokens[ntok++] = (char *)"";
        }
    }
    parse_source(tokens, (int)ntok, 1, env_name);
    free(tokens);
    free(copy);
}
