{
    w->fd = fd;
    w->display = display;
    w->discard = discard;
    w->used = 0;
}

static void writer_flush(Writer *w)
{
    size_t off = 0;
    if (w->discard) {
        w->used = 0;
        return;
    }
    while (off < w->used) {
        ssize_t n = write(w->fd, w->buf + off, w->used - off);
        if (n < 0) {
            if (errno == EINTR)
