        size_t space = sizeof(w->buf) - w->used;
        size_t take = len < space ? len : space;
        memcpy(w->buf + w->used, p, take);
        w->used += take;
        p += take;
        len -= take;
        if (w->used == sizeof(w->buf))
            writer_flush(w);
    }
}

