    unsigned long long total_deflate;
    Buffer history;         /* last up to 32768 bytes before current block */
};

static void compress_one_block(struct compress_ctx *ctx,
                               const unsigned char *data, size_t len, int last)
{
    Buffer *piece;
    ctx->check_crc = (uint32_t)crc32(ctx->check_crc, data, (uInt)len);
    ctx->check_adler = (uint32_t)adler32(ctx->check_adler, data, (uInt)len);
    ctx->total_in += len;
    piece = deflate_block(data, len, ctx->history.data, ctx->history.len,
                          last);
    writer_write(ctx->writer, piece->data, piece->len);
    ctx->total_deflate += piece->len;
    buf_free(piece);
    free(piece);
    if (len > 0) {
        buf_append(&ctx->history, data, len);
        if (ctx->history.len > 32768) {
            size_t drop = ctx->history.len - 32768;
            memmove(ctx->history.data, ctx->history.data + drop,
                    ctx->history.len - drop);
            ctx->history.len -= drop;
        }
    }
}

/* Chunk source for compression input. */
struct chunk_source {
    int fd;
    const char *display;
    size_t block_bytes;
    Buffer pending;
    int eof;
};

static void source_fill(struct chunk_source *src)
{
    unsigned char tmp[65536];
    while (src->pending.len < src->block_bytes && !src->eof) {
        size_t want = src->block_bytes - src->pending.len;
        size_t got;
        if (want > sizeof(tmp))
            want = sizeof(tmp);
        got = read_block(src->fd, tmp, want, src->display);
        if (got == 0) {
            src->eof = 1;
            break;
        }
        buf_append(&src->pending, tmp, got);
        if (got < want)
            src->eof = 1;
    }
}

static int rsync_boundary(const unsigned char *data, size_t len)
{
    uint32_t hash = 0;
    size_t i;
    if (len < 2)
        return 0;
    for (i = 0; i < len; i++) {
        hash = hash * 31U + data[i];
        if (i >= 1 && (hash & 4095U) == 0)
            return (int)(i + 1);
    }
    return 0;
}

/* Return the next chunk, or NULL at end of input. */
static Buffer *source_next(struct chunk_source *src)
{
    Buffer *chunk;
    if (!g.rsyncable) {
        unsigned char *buf = xmalloc(src->block_bytes);
        size_t got = read_block(src->fd, buf, src->block_bytes, src->display);
        if (got == 0) {
            free(buf);
            return NULL;
        }
        chunk = xmalloc(sizeof(*chunk));
        buf_init(chunk);
        buf_append(chunk, buf, got);
        free(buf);
        return chunk;
    }
    source_fill(src);
    if (src->pending.len == 0)
        return NULL;
    {
        size_t take = src->pending.len;
        int cut = rsync_boundary(src->pending.data, src->pending.len);
        if (cut > 0)
            take = (size_t)cut;
        chunk = xmalloc(sizeof(*chunk));
        buf_init(chunk);
        buf_append(chunk, src->pending.data, take);
        if (take < src->pending.len)
            memmove(src->pending.data, src->pending.data + take,
                    src->pending.len - take);
        src->pending.len -= take;
        return chunk;
    }
}

static unsigned char gzip_xfl(void)
{
    if (g.level == 1)
        return 4;
    if (g.level == 9 || g.level == 11)
        return 2;
    return 0;
}

static unsigned short zlib_header(void)
{
    switch (g.level) {
    case 0: return 0x789c;
    case 1: return 0x7801;
    case 2: case 3: case 4: case 5: return 0x789c;
    case 6: case 7: case 8: return 0x785e;
    default: return 0x78da;     /* 9 and 11 */
    }
}

static int name_effective(void)
{
    if (g.name_state >= 0)
        return g.name_state;
    return g.decode || g.test || g.list ? 0 : 1;
}

static int time_effective(void)
{
    if (g.time_state >= 0)
        return g.time_state;
    return g.decode || g.test || g.list ? 0 : 1;
}

static void dos_encode(time_t stamp, unsigned *dos_time, unsigned *dos_date)
{
    struct tm tmv;
    struct tm *res;
    *dos_time = 0;
    *dos_date = 0;
    res = localtime_r(&stamp, &tmv);
    if (res == NULL)
        return;
    if (tmv.tm_year < 80 || tmv.tm_year > 207)
        return;
    *dos_time = (unsigned)(((tmv.tm_hour & 0x1f) << 11) |
                           ((tmv.tm_min & 0x3f) << 5) |
                           ((tmv.tm_sec >> 1) & 0x1f));
    *dos_date = (unsigned)((((tmv.tm_year - 80) & 0x7f) << 9) |
                           (((tmv.tm_mon + 1) & 0xf) << 5) |
                           (tmv.tm_mday & 0x1f));
}
