    struct chunk_source src;
    Buffer *cur;
    char *zip_name = NULL;
    unsigned zip_dos_time = 0, zip_dos_date = 0;
    uint32_t zip_stamp32 = 0;
    size_t zip_local_len = 0;

    if (!info->is_stdin) {
        if (name_effective())
            stored_name = base_name(info->path);
        if (time_effective())
            stored_stamp = info->in_mtime;
    }
    start_verbose(info->display, out_display);
    if (g.format == FORMAT_ZLIB && g.comment != NULL)
        note_msg("can't store comment in zlib format -- ignoring");

    memset(&ctx, 0, sizeof(ctx));
    ctx.writer = writer;
    ctx.check_crc = (uint32_t)crc32(0, Z_NULL, 0);
    ctx.check_adler = (uint32_t)adler32(0, Z_NULL, 0);
    buf_init(&ctx.history);

    if (g.format == FORMAT_GZIP) {
        Buffer hdr;
        unsigned char fixed[10];
        buf_init(&hdr);
        fixed[0] = 0x1f; fixed[1] = 0x8b; fixed[2] = 8;
        fixed[3] = (unsigned char)((stored_name ? 8 : 0) |
                                   (g.comment ? 16 : 0));
        fixed[4] = (unsigned char)(stored_stamp & 0xff);
        fixed[5] = (unsigned char)(((uint32_t)stored_stamp >> 8) & 0xff);
        fixed[6] = (unsigned char)(((uint32_t)stored_stamp >> 16) & 0xff);
        fixed[7] = (unsigned char)(((uint32_t)stored_stamp >> 24) & 0xff);
        fixed[8] = gzip_xfl();
        fixed[9] = 3;
        buf_append(&hdr, fixed, 10);
        if (stored_name)
            buf_append_str(&hdr, stored_name), buf_append_byte(&hdr, 0);
        if (g.comment)
            buf_append_str(&hdr, g.comment), buf_append_byte(&hdr, 0);
        writer_write(writer, hdr.data, hdr.len);
        buf_free(&hdr);
    } else if (g.format == FORMAT_ZLIB) {
        unsigned short h = zlib_header();
        unsigned char b[2];
        b[0] = (unsigned char)(h >> 8);
        b[1] = (unsigned char)(h & 0xff);
        writer_write(writer, b, 2);
    } else { /* zip */
        Buffer hdr;
        time_t dos_source = stored_stamp == 0 ? time(NULL) : stored_stamp;
        if (info->is_stdin)
            zip_name = xstrdup(g.alias ? g.alias : "-");
        else
            zip_name = xstrdup(name_effective() ? base_name(info->path) : "-");
        zip_stamp32 = (uint32_t)stored_stamp;
        dos_encode(dos_source, &zip_dos_time, &zip_dos_date);
        buf_init(&hdr);
        /* local file header */
        {
            unsigned char b4[4];
            b4[0] = 'P'; b4[1] = 'K'; b4[2] = 3; b4[3] = 4;
            buf_append(&hdr, b4, 4);
        }
        {
            Buffer tmp;
            buf_init(&tmp);
            /* build variable parts using a scratch buffer */
            buf_free(&tmp);
        }
        /* version needed 45, flags 8, method 8 */
        {
            unsigned char fields[26];
            memset(fields, 0, sizeof(fields));
            fields[0] = 45; fields[1] = 0;          /* version */
            fields[2] = 8; fields[3] = 0;           /* flags */
            fields[4] = 8; fields[5] = 0;           /* method */
            fields[6] = (unsigned char)(zip_dos_time & 0xff);
            fields[7] = (unsigned char)((zip_dos_time >> 8) & 0xff);
            fields[8] = (unsigned char)(zip_dos_date & 0xff);
            fields[9] = (unsigned char)((zip_dos_date >> 8) & 0xff);
            /* crc = 0 (10..13), sizes = 0xffffffff (14..21) */
            fields[18] = 0xff; fields[19] = 0xff; fields[20] = 0xff; fields[21] = 0xff;
            fields[22] = (unsigned char)(strlen(zip_name) & 0xff);
            fields[23] = (unsigned char)((strlen(zip_name) >> 8) & 0xff);
            fields[24] = 29; fields[25] = 0;        /* extra length */
            /* NOTE: fields layout here is version(2) flags(2) method(2)
             * time(2) date(2) crc(4) csize(4) usize(4) fnlen(2) extralen(2);
             * crc is at offset 10, csize 14, usize 18. */
            fields[14] = 0xff; fields[15] = 0xff; fields[16] = 0xff; fields[17] = 0xff;
            buf_append(&hdr, fields, 26);
        }
        buf_append_str(&hdr, zip_name);
        /* extra: zip64 (16 zero bytes) + UT */
        writer_put16; /* silence accidental macro use if any */
        {
            unsigned char extra[29];
            memset(extra, 0, sizeof(extra));
            extra[0] = 1; extra[1] = 0; extra[2] = 16; extra[3] = 0;
            /* 16 bytes of zero zip64 data at 4..19 */
            extra[20] = 0x55; extra[21] = 0x54; extra[22] = 5; extra[23] = 0;
            extra[24] = 1;
            extra[25] = (unsigned char)(zip_stamp32 & 0xff);
            extra[26] = (unsigned char)((zip_stamp32 >> 8) & 0xff);
            extra[27] = (unsigned char)((zip_stamp32 >> 16) & 0xff);
            extra[28] = (unsigned char)((zip_stamp32 >> 24) & 0xff);
            buf_append(&hdr, extra, 29);
        }
        zip_local_len = hdr.len;
        writer_write(writer, hdr.data, hdr.len);
        buf_free(&hdr);
    }

    memset(&src, 0, sizeof(src));
    src.fd = infd;
    src.display = info->display;
    src.block_bytes = (size_t)g.block_kb * 1024U;
    buf_init(&src.pending);

    cur = source_next(&src);
    if (cur == NULL) {
        static const unsigned char empty_dummy = 0;
        compress_one_block(&ctx, &empty_dummy, 0, 1);
    } else {
        for (;;) {
            Buffer *next = source_next(&src);
            int last = (next == NULL);
            compress_one_block(&ctx, cur->data ? cur->data : (const unsigned char *)"",
                               cur->len, last);
            buf_free(cur);
            free(cur);
            if (last)
                break;
            cur = next;
        }
    }
    buf_free(&src.pending);
    buf_free(&ctx.history);

    if (g.format == FORMAT_GZIP) {
        writer_put32(writer, ctx.check_crc);
        writer_put32(writer, (uint32_t)(ctx.total_in & 0xffffffffULL));
    } else if (g.format == FORMAT_ZLIB) {
        writer_put32be(writer, ctx.check_adler);
    } else {
        size_t name_len = strlen(zip_name);
        size_t comment_len = g.comment ? strlen(g.comment) : 0;
        size_t central_len = 46 + name_len + 9 + comment_len;
        unsigned long long central_offset =
            (unsigned long long)zip_local_len + ctx.total_deflate + 24ULL;
        /* data descriptor */
        writer_write(writer, "PK\x07\x08", 4);
        writer_put32(writer, ctx.check_crc);
        {
            unsigned char b[16];
            int i;
            for (i = 0; i < 8; i++)
                b[i] = (unsigned char)((ctx.total_deflate >> (8 * i)) & 0xff);
            for (i = 0; i < 8; i++)
                b[8 + i] = (unsigned char)((ctx.total_in >> (8 * i)) & 0xff);
            writer_write(writer, b, 16);
        }
        /* central directory */
        writer_write(writer, "PK\x01\x02", 4);
        writer_put16(writer, 0xff2d);
        writer_put16(writer, 45);
        writer_put16(writer, 8);
        writer_put16(writer, 8);
        writer_put16(writer, zip_dos_time);
        writer_put16(writer, zip_dos_date);
        writer_put32(writer, ctx.check_crc);
        writer_put32(writer, (uint32_t)(ctx.total_deflate & 0xffffffffULL));
        writer_put32(writer, (uint32_t)(ctx.total_in & 0xffffffffULL));
        writer_put16(writer, (unsigned)name_len);
        writer_put16(writer, 9);                 /* extra length */
        writer_put16(writer, (unsigned)comment_len);
        writer_put16(writer, 0);                 /* disk start */
        writer_put16(writer, 0);                 /* internal attrs */
        writer_put32(writer, 0);                 /* external attrs */
        writer_put32(writer, 0);                 /* local offset */
        writer_write(writer, zip_name, name_len);
        {
            unsigned char extra[9];
            extra[0] = 0x55; extra[1] = 0x54; extra[2] = 5; extra[3] = 0;
            extra[4] = 1;
            extra[5] = (unsigned char)(zip_stamp32 & 0xff);
            extra[6] = (unsigned char)((zip_stamp32 >> 8) & 0xff);
            extra[7] = (unsigned char)((zip_stamp32 >> 16) & 0xff);
            extra[8] = (unsigned char)((zip_stamp32 >> 24) & 0xff);
            writer_write(writer, extra, 9);
        }
        if (g.comment)
            writer_write(writer, g.comment, comment_len);
        /* end of central directory */
        writer_write(writer, "PK\x05\x06", 4);
        writer_put16(writer, 0);
        writer_put16(writer, 0);
        writer_put16(writer, 1);
        writer_put16(writer, 1);
        writer_put32(writer, (uint32_t)central_len);
        writer_put32(writer, (uint32_t)central_offset);
        writer_put16(writer, 0);
        free(zip_name);
    }
    finish_verbose();
    return PROC_DELETE;
