    char *stored_name;          /* NULL if absent */
    uint32_t gzip_mtime;
    /* zip */
    uint16_t zip_flags;
    uint32_t zip_crc;
    unsigned long long zip_cs;
    unsigned long long zip_us;
    int zip_is64;
    int zip_has_ut;
    uint32_t zip_ut;
    time_t zip_stamp;           /* if no UT extra */
};

static uint16_t get_le16(const unsigned char *p)
{
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t get_le32(const unsigned char *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static uint64_t get_le64(const unsigned char *p)
{
    uint64_t v = 0;
    int i;
    for (i = 7; i >= 0; i--)
        v = (v << 8) | p[i];
    return v;
}

static uint32_t get_be32(const unsigned char *p)
{
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static time_t dos_to_time(unsigned dos_time, unsigned dos_date)
{
    struct tm tmv;
    if (dos_time == 0 && dos_date == 0)
        return time(NULL);
    memset(&tmv, 0, sizeof(tmv));
    tmv.tm_year = (int)(((dos_date >> 9) & 0x7f) + 80);
    tmv.tm_mon = (int)(((dos_date >> 5) & 0xf) - 1);
    tmv.tm_mday = (int)(dos_date & 0x1f);
    tmv.tm_hour = (int)((dos_time >> 11) & 0x1f);
    tmv.tm_min = (int)((dos_time >> 5) & 0x3f);
    tmv.tm_sec = (int)((dos_time & 0x1f) * 2);
    tmv.tm_isdst = -1;
    return mktime(&tmv);
}

static void head_init(struct head_info *h)
{
    memset(h, 0, sizeof(*h));
    h->stored_name = NULL;
}

static void head_free(struct head_info *h)
{
    free(h->stored_name);
    h->stored_name = NULL;
}

/* Parse a header at data[pos..len).  check_method distinguishes the
 * decompressor (unknown methods are an error) from the lister. */
static enum head_status parse_header(const unsigned char *data, size_t len,
                                     size_t pos, int check_method,
                                     struct head_info *h)
{
    size_t rem;
    head_init(h);
    if (pos >= len)
        return HEAD_EMPTY;
    rem = len - pos;
    data += pos;

    if (data[0] == 0x1f) {
        size_t p;
        unsigned flags;
        if (rem < 2 || data[1] != 0x8b)
            return HEAD_FAIL;
        if (rem < 3)
            return HEAD_FAIL;
        h->format = FORMAT_GZIP;
        h->method = data[2];
        if (check_method && h->method != 8)
            return HEAD_UNKNOWN;
        if (rem < 10)
            return HEAD_FAIL;
        flags = data[3];
        if (flags & 0xe0)
            return HEAD_FAIL;
        h->gzip_mtime = get_le32(data + 4);
        p = 10;
        if (flags & 4) {
            size_t xlen;
            if (rem < p + 2)
                return HEAD_FAIL;
            xlen = get_le16(data + p);
            p += 2;
            if (rem < p + xlen)
                return HEAD_FAIL;
            p += xlen;
        }
        if (flags & 8) {
            size_t start = p;
            while (p < rem && data[p] != 0)
                p++;
            if (p >= rem)
                return HEAD_FAIL;
            h->stored_name = xstrndup((const char *)data + start, p - start);
            p++;
        }
        if (flags & 16) {
            while (p < rem && data[p] != 0)
                p++;
            if (p >= rem)
                return HEAD_FAIL;
            p++;
        }
        if (flags & 2) {
            uint32_t crc;
            if (rem < p + 2)
                return HEAD_FAIL;
            crc = crc32(0, data, (uInt)p) & 0xffff;
            if (crc != get_le16(data + p))
                return HEAD_CRC;
            p += 2;
        }
        h->header_len = p;
        return HEAD_OK;
    }

    if (data[0] == 'P') {
        size_t fnlen, extralen, p;
        uint32_t cs32, us32;
        const unsigned char *extra;
        size_t exleft;
        if (rem < 4 || data[1] != 'K' || data[2] != 3 || data[3] != 4)
            return HEAD_FAIL;
        if (rem < 30)
            return HEAD_FAIL;
        h->format = FORMAT_ZIP;
        h->zip_flags = get_le16(data + 6);
        h->method = get_le16(data + 8);
        if (h->zip_flags & (uint16_t)~0x080f)
            return HEAD_FAIL;
        h->zip_crc = get_le32(data + 14);
        cs32 = get_le32(data + 18);
        us32 = get_le32(data + 22);
        fnlen = get_le16(data + 26);
        extralen = get_le16(data + 28);
        if (rem < 30 + fnlen + extralen)
            return HEAD_FAIL;
        h->stored_name = xstrndup((const char *)data + 30, fnlen);
        extra = data + 30 + fnlen;
        exleft = extralen;
        h->zip_cs = cs32;
        h->zip_us = us32;
        h->zip_is64 = (cs32 == 0xffffffffUL || us32 == 0xffffffffUL);
        h->zip_stamp = dos_to_time(get_le16(data + 10), get_le16(data + 12));
        p = 0;
        while (exleft >= 4) {
            unsigned tag = get_le16(extra + p);
            unsigned sz = get_le16(extra + p + 2);
            const unsigned char *val;
            if ((size_t)sz > exleft - 4)
                break;
            val = extra + p + 4;
            if (tag == 0x0001) {
                size_t off = 0;
                if (us32 == 0xffffffffUL && sz >= 8) {
                    h->zip_us = get_le64(val);
                    off += 8;
                }
                if (cs32 == 0xffffffffUL && sz >= off + 8) {
                    h->zip_cs = get_le64(val + off);
                }
            } else if (tag == 0x5455) {
                if (sz >= 5 && (val[0] & 1)) {
                    h->zip_has_ut = 1;
                    h->zip_ut = get_le32(val + 1);
                }
            }
            p += 4 + sz;
            exleft -= 4 + sz;
        }
        h->header_len = 30 + fnlen + extralen;
        return HEAD_OK;
    }

    /* zlib */
    if (rem < 2)
        return HEAD_FAIL;
    {
        unsigned b0 = data[0], b1 = data[1];
        if ((b0 & 0xf) != 8 || (b0 >> 4) > 7 ||
            (((b0 << 8) + b1) % 31) != 0 || (b1 & 0x20) != 0)
            return HEAD_FAIL;
        h->format = FORMAT_ZLIB;
        h->method = 8;
        h->header_len = 2;
        return HEAD_OK;
    }
}
