/* ---------- decompression ---------- */

struct inflate_outcome {
    int state;                  /* 0 end, 1 data error, 2 incomplete */
    unsigned long long out_len;
    uint32_t crc;
    uint32_t adler;
    size_t consumed;
    const char *msg;
};

static void inflate_member(const unsigned char *data, size_t len,
                           Writer *writer, struct inflate_outcome *res)
{
    z_stream strm;
    unsigned char outbuf[65536];
    memset(res, 0, sizeof(*res));
    res->crc = (uint32_t)crc32(0, Z_NULL, 0);
    res->adler = (uint32_t)adler32(0, Z_NULL, 0);
    memset(&strm, 0, sizeof(strm));
    if (inflateInit2(&strm, -15) != Z_OK)
        abort_msg(EINVAL, "zlib initialization failed");
    strm.next_in = (unsigned char *)(uintptr_t)data;
    strm.avail_in = (uInt)len;
    for (;;) {
        size_t produced;
        int ret;
        strm.next_out = outbuf;
        strm.avail_out = sizeof(outbuf);
        ret = inflate(&strm, Z_NO_FLUSH);
        produced = sizeof(outbuf) - strm.avail_out;
        if (produced > 0) {
            writer_write(writer, outbuf, produced);
            res->crc = (uint32_t)crc32(res->crc, outbuf, (uInt)produced);
            res->adler = (uint32_t)adler32(res->adler, outbuf, (uInt)produced);
            res->out_len += produced;
        }
        if (ret == Z_STREAM_END) {
            res->state = 0;
            res->consumed = (size_t)strm.total_in;
            break;
        }
        if (ret == Z_DATA_ERROR) {
            res->state = 1;
            res->msg = strm.msg;
            res->consumed = (size_t)strm.total_in;
            break;
        }
        if (ret == Z_OK || ret == Z_BUF_ERROR) {
            if (strm.avail_in == 0) {
                res->state = 2;
                res->consumed = (size_t)strm.total_in;
                break;
            }
            if (ret == Z_BUF_ERROR && produced == 0) {
                res->state = 2;
                res->consumed = (size_t)strm.total_in;
                break;
            }
            continue;
        }
        res->state = 1;
        res->msg = strm.msg;
        res->consumed = (size_t)strm.total_in;
        break;
    }
    inflateEnd(&strm);
}

static int first_header_error(struct input_info *info, enum head_status st)
{
    switch (st) {
    case HEAD_EMPTY:
        return skip_msg("%s empty", info->display);
    case HEAD_UNKNOWN:
        return skip_msg("%s unknown compression method", info->display);
    case HEAD_CRC:
        return skip_msg("%s corrupt: header crc error", info->display);
    default:
        return skip_msg("%s unrecognized format", info->display);
    }
}

static int run_decompress(struct input_info *info, Buffer *input,
                          Writer *writer, int test_mode,
                          const char *out_display,
                          struct head_info *first_out)
{
    struct head_info head;
    enum head_status st;
    size_t pos = 0;

    if (input->len == 0)
        return first_header_error(info, HEAD_EMPTY);
    st = parse_header(input->data, input->len, 0, 1, &head);
    if (st != HEAD_OK) {
        head_free(&head);
        return first_header_error(info, st);
    }
    if (head.format == FORMAT_ZIP &&
        (head.method != 8 || (head.zip_flags & 1))) {
        head_free(&head);
        return skip_msg("%s unknown compression method", info->display);
    }
    if (first_out != NULL) {
        *first_out = head;
        head.stored_name = NULL;
    }
    if (!test_mode)
        start_verbose(info->display, out_display);

    if (head.format == FORMAT_ZIP) {
        struct inflate_outcome res;
        size_t data_start = head.header_len;
        size_t after;
        unsigned long long expect_crc, expect_cs, expect_us;
        inflate_member(input->data + data_start, input->len - data_start,
                       writer, &res);
        if (res.state == 1) {
            skip_msg("%s: corrupted -- invalid deflate data (%s)",
                     info->display, res.msg ? res.msg : "unknown");
            finish_verbose();
            head_free(&head);
            return PROC_FAIL;
        }
        if (res.state == 2) {
            skip_msg("%s: corrupted -- incomplete deflate data", info->display);
            finish_verbose();
            head_free(&head);
            return PROC_FAIL;
        }
        after = data_start + res.consumed;
        expect_crc = head.zip_crc;
        expect_cs = head.zip_cs;
        expect_us = head.zip_us;
        if (head.zip_flags & 8) {
            size_t cursor = after;
            size_t width = head.zip_is64 ? 8 : 4;
            uint64_t dcs, dus;
            if (cursor + 4 <= input->len &&
                memcmp(input->data + cursor, "PK\x07\x08", 4) == 0)
                cursor += 4;
            if (cursor + 4 + 2 * width > input->len) {
                skip_msg("%s: corrupted entry -- missing trailer", info->display);
                finish_verbose();
                head_free(&head);
                return PROC_FAIL;
            }
            expect_crc = get_le32(input->data + cursor);
            cursor += 4;
            dcs = width == 8 ? get_le64(input->data + cursor)
                             : get_le32(input->data + cursor);
            cursor += width;
            dus = width == 8 ? get_le64(input->data + cursor)
                             : get_le32(input->data + cursor);
            cursor += width;
            expect_cs = dcs;
            expect_us = dus;
            after = cursor;
        }
        if ((unsigned long long)res.crc != expect_crc) {
            skip_msg("%s: corrupted entry -- crc32 mismatch", info->display);
            finish_verbose();
            head_free(&head);
            return PROC_FAIL;
        }
        if (res.out_len != expect_us ||
            (unsigned long long)res.consumed != expect_cs) {
            skip_msg("%s: corrupted entry -- length mismatch", info->display);
            finish_verbose();
            head_free(&head);
            return PROC_FAIL;
        }
        {
            int more = (after + 4 <= input->len &&
                        memcmp(input->data + after, "PK\x03\x04", 4) == 0);
            finish_verbose();
            head_free(&head);
            if (more) {
                warn_msg("%s: entries after the first were ignored",
                         info->display);
                return PROC_KEEP;
            }
        }
        return PROC_DELETE;
    }

    /* gzip and zlib members */
    {
        struct head_info cur = head;
        /* stored_name ownership conceptually stays in cur/first_out;
         * it is not needed for stream processing. */
        for (;;) {
            struct inflate_outcome res;
            size_t data_start = pos + cur.header_len;
            size_t after;
            int format = cur.format;
            inflate_member(input->data + data_start, input->len - data_start,
                           writer, &res);
            if (res.state == 1) {
                skip_msg("%s: corrupted -- invalid deflate data (%s)",
                         info->display, res.msg ? res.msg : "unknown");
                finish_verbose();
                head_free(&cur);
                return PROC_FAIL;
            }
            if (res.state == 2) {
                skip_msg("%s: corrupted -- incomplete deflate data",
                         info->display);
                finish_verbose();
                head_free(&cur);
                return PROC_FAIL;
            }
            after = data_start + res.consumed;
            if (format == FORMAT_GZIP) {
                uint32_t want_crc, want_len;
                if (after + 8 > input->len) {
                    skip_msg("%s: corrupted -- missing trailer", info->display);
                    finish_verbose();
                    head_free(&cur);
                    return PROC_FAIL;
                }
                want_crc = get_le32(input->data + after);
                want_len = get_le32(input->data + after + 4);
                if (res.crc != want_crc) {
                    skip_msg("%s: corrupted -- crc32 mismatch", info->display);
                    finish_verbose();
                    head_free(&cur);
                    return PROC_FAIL;
                }
                if ((res.out_len & 0xffffffffULL) != want_len) {
                    skip_msg("%s: corrupted -- length mismatch", info->display);
                    finish_verbose();
                    head_free(&cur);
                    return PROC_FAIL;
                }
                pos = after + 8;
                head_free(&cur);
                if (pos >= input->len) {
                    finish_verbose();
                    return PROC_DELETE;
                }
                /* Parse the next member. */
                st = parse_header(input->data, input->len, pos, 1, &cur);
                if (st != HEAD_OK) {
                    head_free(&cur);
                    if (g.verbosity > 0)
                        warn_msg("%s: trailing junk was ignored", info->display);
                    finish_verbose();
                    return PROC_DELETE;
                }
                if (cur.format == FORMAT_ZIP) {
                    /* A zip entry can follow a gzip member; process it
                     * as a terminal member. */
                    Buffer *sub;
                    (void)sub;
                    if (cur.method != 8 || (cur.zip_flags & 1)) {
                        /* In practice this cannot be reached for the
                         * common cases; treat as trailing junk. */
                        head_free(&cur);
                        if (g.verbosity > 0)
                            warn_msg("%s: trailing junk was ignored",
                                     info->display);
                        finish_verbose();
                        return PROC_DELETE;
                    }
                    /* Decompress the zip entry inline. */
                    {
                        struct inflate_outcome zres;
                        size_t zstart = pos + cur.header_len;
                        size_t zafter;
                        unsigned long long ecrc = cur.zip_crc;
                        unsigned long long ecs = cur.zip_cs;
                        unsigned long long eus = cur.zip_us;
                        inflate_member(input->data + zstart,
                                       input->len - zstart, writer, &zres);
                        if (zres.state != 0) {
                            if (zres.state == 1)
                                skip_msg("%s: corrupted -- invalid deflate data (%s)",
                                         info->display,
                                         zres.msg ? zres.msg : "unknown");
                            else
                                skip_msg("%s: corrupted -- incomplete deflate data",
                                         info->display);
                            finish_verbose();
                            head_free(&cur);
                            return PROC_FAIL;
                        }
                        zafter = zstart + zres.consumed;
                        if (cur.zip_flags & 8) {
                            size_t cursor = zafter;
                            size_t width = cur.zip_is64 ? 8 : 4;
                            if (cursor + 4 <= input->len &&
                                memcmp(input->data + cursor, "PK\x07\x08", 4) == 0)
                                cursor += 4;
                            if (cursor + 4 + 2 * width > input->len) {
                                skip_msg("%s: corrupted entry -- missing trailer",
                                         info->display);
                                finish_verbose();
                                head_free(&cur);
                                return PROC_FAIL;
                            }
                            ecrc = get_le32(input->data + cursor);
                            cursor += 4;
                            ecs = width == 8 ? get_le64(input->data + cursor)
                                             : get_le32(input->data + cursor);
                            cursor += width;
                            eus = width == 8 ? get_le64(input->data + cursor)
                                             : get_le32(input->data + cursor);
                            zafter = cursor;
                        }
                        if ((unsigned long long)zres.crc != ecrc) {
                            skip_msg("%s: corrupted entry -- crc32 mismatch",
                                     info->display);
                            finish_verbose();
                            head_free(&cur);
                            return PROC_FAIL;
                        }
                        if (zres.out_len != eus ||
                            (unsigned long long)zres.consumed != ecs) {
                            skip_msg("%s: corrupted entry -- length mismatch",
                                     info->display);
                            finish_verbose();
                            head_free(&cur);
                            return PROC_FAIL;
                        }
                        {
                            int more = (zafter + 4 <= input->len &&
                                        memcmp(input->data + zafter,
                                               "PK\x03\x04", 4) == 0);
                            finish_verbose();
                            head_free(&cur);
                            if (more) {
                                warn_msg("%s: entries after the first were ignored",
                                         info->display);
                                return PROC_KEEP;
                            }
                        }
                        return PROC_DELETE;
                    }
                }
                if (cur.format == FORMAT_ZLIB) {
                    /* A zlib member after gzip: decode it, then stop. */
                    struct inflate_outcome zres;
                    size_t zstart = pos + cur.header_len;
                    size_t zafter;
                    inflate_member(input->data + zstart,
                                   input->len - zstart, writer, &zres);
                    if (zres.state != 0) {
                        if (zres.state == 1)
                            skip_msg("%s: corrupted -- invalid deflate data (%s)",
                                     info->display,
                                     zres.msg ? zres.msg : "unknown");
                        else
                            skip_msg("%s: corrupted -- incomplete deflate data",
                                     info->display);
                        finish_verbose();
                        head_free(&cur);
                        return PROC_FAIL;
                    }
                    zafter = zstart + zres.consumed;
                    if (zafter + 4 > input->len) {
                        skip_msg("%s: corrupted -- missing trailer",
                                 info->display);
                        finish_verbose();
                        head_free(&cur);
                        return PROC_FAIL;
                    }
                    if (zres.adler != get_be32(input->data + zafter)) {
                        skip_msg("%s: corrupted -- adler32 mismatch",
                                 info->display);
                        finish_verbose();
                        head_free(&cur);
                        return PROC_FAIL;
                    }
                    zafter += 4;
                    head_free(&cur);
                    if (zafter < input->len)
                        warn_msg("%s: trailing junk was ignored", info->display);
                    finish_verbose();
                    return PROC_DELETE;
                }
                /* otherwise another gzip member: continue the loop */
                continue;
            } else { /* zlib first member */
                if (after + 4 > input->len) {
                    skip_msg("%s: corrupted -- missing trailer", info->display);
                    finish_verbose();
                    head_free(&cur);
                    return PROC_FAIL;
                }
                if (res.adler != get_be32(input->data + after)) {
                    skip_msg("%s: corrupted -- adler32 mismatch", info->display);
                    finish_verbose();
                    head_free(&cur);
                    return PROC_FAIL;
                }
                after += 4;
                head_free(&cur);
                if (after < input->len)
                    warn_msg("%s: trailing junk was ignored", info->display);
                finish_verbose();
                return PROC_DELETE;
            }
        }
    }
}
