static void inflate_member(const unsigned char *data, size_t len,
                           Writer *writer, struct inflate_outcome *res)
{
    z_stream strm;
    unsigned char outbuf[65536];
    memset(res, 0, sizeof(*res));
    res->crc = (uint32_t)crc32(0, Z_NULL, 0);
    res->adler = (uint32_t)adler32(0, Z_NULL, 0);
    memset(&strm, 0, sizeof(strm));
    if (inflateInit2(&strm, -15) != Z_OK)
        abort_msg(EINVAL, "zlib initialization failed");
    strm.next_in = (unsigned char *)(uintptr_t)data;
    strm.avail_in = (uInt)len;
    for (;;) {
        size_t produced;
        int ret;
        strm.next_out = outbuf;
        strm.avail_out = sizeof(outbuf);
        ret = inflate(&strm, Z_NO_FLUSH);
        produced = sizeof(outbuf) - strm.avail_out;
        if (produced > 0) {
            writer_write(writer, outbuf, produced);
            res->crc = (uint32_t)crc32(res->crc, outbuf, (uInt)produced);
            res->adler = (uint32_t)adler32(res->adler, outbuf, (uInt)produced);
            res->out_len += produced;
