        if (ret == Z_STREAM_END) {
            res->state = 0;
            res->consumed = (size_t)strm.total_in;
            break;
        }
        if (ret == Z_DATA_ERROR) {
            res->state = 1;
            res->msg = strm.msg;
            res->consumed = (size_t)strm.total_in;
            break;
        }
        if (ret == Z_OK || ret == Z_BUF_ERROR) {
            if (strm.avail_in == 0) {
                res->state = 2;
                res->consumed = (size_t)strm.total_in;
