{"command":"cat >> pigz.c << 'EOF'

/* ---------- per-file processing ---------- */

static int process_named_any(const char *path);

static void set_cleanup(const char *path)
{
    free(g.out_unlink);
    g.out_unlink = xstrdup(path);
}

static void clear_cleanup(void)
{
    free(g.out_unlink);
    g.out_unlink = NULL;
}

static int open_input(struct input_info *info)
{
    int fd;
    if (info->is_stdin)
        return STDIN_FILENO;
    fd = open(info->path, O_RDONLY);
    if (fd < 0)
        abort_read(info->display);
    return fd;
}

static void finish_file_output(Writer *w, const char *outname,
                               struct input_info *info, time_t stamp)
{
    struct timeval tv[2];
    writer_flush(w);
    if (g.synchronous) {
        struct stat sb;
        if (fstat(w->fd, &sb) == 0 && S_ISREG(sb.st_mode))
            (void)fsync(w->fd);
    }
    (void)fchmod(w->fd, info->out_mode);
    if (close(w->fd) != 0)
        abort_write_e(outname, errno ? errno : EIO);
    tv[0].tv_sec = time(NULL);
    tv[0].tv_usec = 0;
    tv[1].tv_sec = stamp;
    tv[1].tv_usec = 0;
    (void)utimes(outname, tv);
    clear_cleanup();
}

static void discard_file_output(Writer *w, const char *outname)
{
    writer_flush(w);
    (void)close(w->fd);
    (void)unlink(outname);
    clear_cleanup();
}

static int open_output_file(const char *outname)
{
    int fd = open(outname, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (fd < 0)
        abort_write(outname);
    set_cleanup(outname);
    return fd;
}

static time_t decompress_stamp(struct input_info *info,
                               struct head_info *head)
{
    time_t stamp = info->in_mtime;
    if (!time_effective())
        return stamp;
    if (head->format == FORMAT_GZIP) {
        if (head->gzip_mtime != 0)
            stamp = (time_t)(int32_t)head->gzip_mtime;
    } else if (head->format == FORMAT_ZIP) {
        if (head->zip_has_ut) {
            if (head->zip_ut != 0)
                stamp = (time_t)(int32_t)head->zip_ut;
        } else {
            stamp = head->zip_stamp;
        }
    }
    return stamp;
}

static char *strip_compressed_suffix(const char *path)
{
    static const char *suffixes[] = {
        ".gz", ".zz", ".zip", ".z", ".Z", "-gz", "-z", "_z", NULL
    };
    size_t len = strlen(path);
    int i;
    if (len > 4 && ends_with(path, ".tgz")) {
        char *out = xstrdup(path);
        out[len - 2] = 'a';
        out[len - 1] = 'r';
        return out;
    }
    for (i = 0; suffixes[i] != NULL; i++) {
        size_t sl = strlen(suffixes[i]);
        if (len > sl && ends_with(path, suffixes[i]))
            return xstrndup(path, len - sl);
    }
    return NULL;
}

static int handle_decompress_to_file(struct input_info *info)
{
    char *tentative;
    char *outname = NULL;
    int infd;
    Buffer *data;
    struct head_info prelim;
    enum head_status pst;
    Writer writer;
    struct head_info first;
    int result;
    time_t stamp;

    tentative = strip_compressed_suffix(info->path);
    if (tentative == NULL)
        return skip_msg("%s does not have compressed suffix", info->display);
    infd = open_input(info);
    data = load_all(infd, info->display);
    close(infd);
    if (data->len == 0) {
        buf_free(data);
        free(data);
        free(tentative);
        return first_header_error(info, HEAD_EMPTY);
    }
    pst = parse_header(data->data, data->len, 0, 1, &prelim);
    if (pst != HEAD_OK) {
        head_free(&prelim);
        buf_free(data);
        free(data);
        free(tentative);
        return first_header_error(info, pst);
    }
    if (prelim.format == FORMAT_ZIP &&
        (prelim.method != 8 || (prelim.zip_flags & 1))) {
        head_free(&prelim);
        buf_free(data);
        free(data);
        free(tentative);
        return skip_msg("%s unknown compression method", info->display);
    }
    if (name_effective() && prelim.stored_name != NULL) {
        const char *base = base_name(prelim.stored_name);
        const char *slash = strrchr(tentative, '/');
        if (slash != NULL) {
            size_t prefix = (size_t)(slash - tentative) + 1;
            outname = xmalloc(prefix + strlen(base) + 1);
            memcpy(outname, tentative, prefix);
            strcpy(outname + prefix, base);
        } else {
            outname = xstrdup(base);
        }
        free(tentative);
    } else {
        outname = tentative;
    }
    head_free(&prelim);

    if (!g.force) {
        struct stat sb;
        if (lstat(outname, &sb) == 0) {
            int r = skip_msg("%s exists", outname);
            free(outname);
            buf_free(data);
            free(data);
            return r;
        }
    }
    {
        int outfd = open_output_file(outname);
        writer_init(&writer, outfd, outname, 0);
    }
    memset(&first, 0, sizeof(first));
    result = run_decompress(info, data, &writer, 0, outname, &first);
    stamp = decompress_stamp(info, &first);
    head_free(&first);
    if (result != PROC_FAIL)
        finish_file_output(&writer, outname, info, stamp);
    else
        discard_file_output(&writer, outname);
    buf_free(data);
    free(data);
    free(outname);
    return result;
}

static int handle_decompress_stdout_or_test(struct input_info *info, int infd)
{
    Buffer *data = load_all(infd, info->display);
    Writer writer;
    int result;
    if (!info->is_stdin)
        close(infd);
    if (g.test)
        writer_init(&writer, -1, info->display, 1);
    else
        writer_init(&writer, STDOUT_FILENO, "<stdout>", 0);
    result = run_decompress(info, data, &writer, g.test,
                            g.test ? info->display : "<stdout>", NULL);
    if (!g.test)
        writer_flush(&writer);
    buf_free(data);
    free(data);
    return result;
}

static int handle_compress(struct input_info *info, int infd, int outfd,
                           const char *outname)
{
    Writer writer;
    int result;
    if (outname == NULL) {
        writer_init(&writer, STDOUT_FILENO, "<stdout>", 0);
        result = run_compress(info, infd, &writer, "<stdout>");
        writer_flush(&writer);
        return result;
    }
    writer_init(&writer, outfd, outname, 0);
    result = run_compress(info, infd, &writer, outname);
    if (result != PROC_FAIL)
        finish_file_output(&writer, outname, info, info->in_mtime);
    else
        discard_file_output(&writer, outname);
    return result;
}

static int post_process(struct input_info *info, int result)
{
    if (result == PROC_FAIL)
        return 1;
    if (result != PROC_DELETE)
        return 0;
    if (g.list || g.test || g.to_stdout || info->is_stdin)
        return 0;
    if (g.keep)
        return 0;
    if (!info->is_regular)
        return 0;
    if (info->has_stat && info->st.st_nlink > 1) {
