    result = run_decompress(info, data, &writer, 0, outname, &first);
    stamp = decompress_stamp(info, &first);
    head_free(&first);
    if (result != PROC_FAIL)
        finish_file_output(&writer, outname, info, stamp);
    else
        discard_file_output(&writer, outname);
    buf_free(data);
    free(data);
    free(outname);
    return result;
}

static int handle_decompress_stdout_or_test(struct input_info *info, int infd)
{
    Buffer *data = load_all(infd, info->display);
    Writer writer;
    int result;
    if (!info->is_stdin)
        close(infd);
    if (g.test)
        writer_init(&writer, -1, info->display, 1);
    else
        writer_init(&writer, STDOUT_FILENO, "<stdout>", 0);
    result = run_decompress(info, data, &writer, g.test,
                            g.test ? info->display : "<stdout>", NULL);
    if (!g.test)
        writer_flush(&writer);
    buf_free(data);
    free(data);
    return result;
}

static int handle_compress(struct input_info *info, int infd, int outfd,
                           const char *outname)
{
    Writer writer;
    int result;
    if (outname == NULL) {
        writer_init(&writer, STDOUT_FILENO, "<stdout>", 0);
        result = run_compress(info, infd, &writer, "<stdout>");
        writer_flush(&writer);
        return result;
    }
    writer_init(&writer, outfd, outname, 0);
    result = run_compress(info, infd, &writer, outname);
    if (result != PROC_FAIL)
        finish_file_output(&writer, outname, info, info->in_mtime);
    else
        discard_file_output(&writer, outname);
    return result;
}

static int post_process(struct input_info *info, int result)
{
    if (result == PROC_FAIL)
        return 1;
    if (result != PROC_DELETE)
        return 0;
    if (g.list || g.test || g.to_stdout || info->is_stdin)
        return 0;
    if (g.keep)
        return 0;
    if (!info->is_regular)
        return 0;
    if (info->has_stat && info->st.st_nlink > 1) {
        note_msg("%s has hard links -- not unlinking", info->path);
        return 1;
    }
    (void)unlink(info->path);
    return 0;
}

static int process_directory(const char *path)
{
    DIR *dir = opendir(path);
    struct dirent *de;
    int ret = 0;
    if (dir == NULL)
        return 0;
    while ((de = readdir(dir)) != NULL) {
        char *child;
        size_t plen;
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0)
            continue;
        plen = strlen(path);
        if (plen > 0 && path[plen - 1] == '/') {
            child = xmalloc(plen + strlen(de->d_name) + 1);
            strcpy(child, path);
            strcat(child, de->d_name);
        } else {
            child = xmalloc(plen + strlen(de->d_name) + 2);
            strcpy(child, path);
            strcat(child, "/");
            strcat(child, de->d_name);
        }
        if (process_named_any(child) != 0)
            ret = 1;
        free(child);
    }
    closedir(dir);
    return ret;
}

static int process_named_any(const char *path)
{
    struct stat lst, eff;
    struct input_info info;
    int have_eff = 1;
    int post_status = 0;
    int result = 0;

    if (lstat(path, &lst) != 0)
        return skip_msg("%s does not exist", path);
    if (S_ISLNK(lst.st_mode) && !g.force)
        return skip_msg("%s is a symbolic link", path);
    eff = lst;
    if (S_ISLNK(lst.st_mode)) {
        if (stat(path, &eff) != 0)
            have_eff = 0;
    }
    if (have_eff && S_ISDIR(eff.st_mode)) {
        if (g.recursive)
            return process_directory(path);
        return skip_msg("%s is a directory", path);
    }
    if (have_eff && (S_ISCHR(eff.st_mode) || S_ISBLK(eff.st_mode) ||
                     S_ISSOCK(eff.st_mode)))
        return skip_msg("%s is a special file or device", path);

    memset(&info, 0, sizeof(info));
    info.path = path;
    info.display = path;
    info.is_stdin = 0;
    info.has_stat = 1;
    info.st = eff;
    info.is_regular = have_eff && S_ISREG(eff.st_mode);
    info.out_mode = info.is_regular ? (mode_t)(eff.st_mode & 01777) : 0600;
    info.in_mtime = eff.st_mtime;

    if (g.list) {
        int fd = open_input(&info);
        Buffer *data = load_all(fd, info.display);
        close(fd);
        result = run_list(&info, data);
        buf_free(data);
        free(data);
        return result;
    }
    if (g.test || g.decode) {
        if (g.test || g.to_stdout) {
            int fd = open_input(&info);
            result = handle_decompress_stdout_or_test(&info, fd);
        } else {
            result = handle_decompress_to_file(&info);
        }
        post_status = post_process(&info, result);
        return post_status ? 1 : (result == PROC_FAIL ? 1 : 0);
    }

    /* compression */
    {
        char *outname = xmalloc(strlen(path) + strlen(g.suffix) + 1);
        int fd;
        strcpy(outname, path);
        strcat(outname, g.suffix);
        if (!g.force && ends_with(path, g.suffix)) {
            int r = skip_msg_quiet_ret("%s ends with %s", path, g.suffix);
            free(outname);
            return r;
        }
        fd = open_input(&info);
        if (g.to_stdout) {
            if (!g.force && isatty(STDOUT_FILENO))
                abort_msg(EINVAL,
                          "trying to write compressed data to a terminal (use -f to force)");
            result = handle_compress(&info, fd, -1, NULL);
            close(fd);
        } else {
            if (!g.force) {
                struct stat sb;
                if (lstat(outname, &sb) == 0) {
                    int r = skip_msg("%s exists", outname);
                    close(fd);
                    free(outname);
                    return r;
                }
            }
            {
                int outfd = open_output_file(outname);
                result = handle_compress(&info, fd, outfd, outname);
            }
            close(fd);
        }
        free(outname);
        post_status = post_process(&info, result);
        return post_status ? 1 : (result == PROC_FAIL ? 1 : 0);
    }
}

static int process_stdin(void)
{
    struct input_info info;
    int result = 0;
    memset(&info, 0, sizeof(info));
    info.path = NULL;
    info.display = "<stdin>";
    info.is_stdin = 1;
    info.out_mode = 0600;
    {
        struct stat sb;
        if (fstat(STDIN_FILENO, &sb) == 0) {
            info.has_stat = 1;
            info.st = sb;
            info.is_regular = S_ISREG(sb.st_mode);
            info.in_mtime = sb.st_mtime;
        }
    }
    if (g.list) {
        Buffer *data = load_all(STDIN_FILENO, info.display);
        result = run_list(&info, data);
        buf_free(data);
        free(data);
        return result;
    }
    if (g.test || g.decode) {
        return handle_decompress_stdout_or_test(&info, STDIN_FILENO);
    }
    if (!g.force && isatty(STDOUT_FILENO))
        abort_msg(EINVAL,
                  "trying to write compressed data to a terminal (use -f to force)");
    result = handle_compress(&info, STDIN_FILENO, -1, NULL);
    return result == PROC_FAIL ? 1 : 0;
}
