{"command":"cat > /tmp/zopfli_lite.c.part << 'EOF'

/* ---------- a compact optimal-parse deflater for level 11 ---------- */

typedef struct {
    Buffer buf;
    uint32_t bitbuf;
    int bitcnt;
    size_t bits;
} BitWriter;

static void bw_init(BitWriter *bw)
{
    buf_init(&bw->buf);
    bw->bitbuf = 0;
    bw->bitcnt = 0;
    bw->bits = 0;
}

static void bw_bits(BitWriter *bw, unsigned value, int count)
{
    int i;
    for (i = 0; i < count; i++) {
        unsigned bit = (value >> i) & 1U;
        if (bit)
            bw->bitbuf |= (1U << bw->bitcnt);
        bw->bitcnt++;
        bw->bits++;
        if (bw->bitcnt == 8) {
            buf_append_byte(&bw->buf, (unsigned char)(bw->bitbuf & 0xff));
            bw->bitbuf = 0;
            bw->bitcnt = 0;
        }
    }
}

static void bw_code(BitWriter *bw, unsigned code, int len)
{
    unsigned rev = 0;
    int i;
    for (i = 0; i < len; i++)
        if (code & (1U << (len - 1 - i)))
            rev |= (1U << i);
    bw_bits(bw, rev, len);
}

static void bw_finish_byte(BitWriter *bw)
{
    if (bw->bitcnt > 0) {
        buf_append_byte(&bw->buf, (unsigned char)(bw->bitbuf & 0xff));
        bw->bitbuf = 0;
        bw->bitcnt = 0;
    }
}

