static void bw_bits(BitWriter *bw, unsigned value, int count)
{
    int i;
    for (i = 0; i < count; i++) {
        if ((value >> i) & 1U)
            bw->bitbuf |= (1U << bw->bitcnt);
        bw->bitcnt++;
        bw->bits++;
