{
    unsigned rev = 0;
    int i;
    for (i = 0; i < len; i++)
        if (code & (1U << (len - 1 - i)))
            rev |= (1U << i);
    bw_bits(bw, rev, len);
}

static void bw_flush_partial(BitWriter *bw)
{
    if (bw->bitcnt > 0) {
        buf_append_byte(&bw->buf, (unsigned char)(bw->bitbuf & 0xff));
        bw->bitbuf = 0;
        bw->bitcnt = 0;
    }
