            int m1 = 0, m2 = 1, t;
            if (nfreq[active[m2]] < nfreq[active[m1]]) { t = m1; m1 = m2; m2 = t; }
            for (i = 2; i < na; i++) {
                if (nfreq[active[i]] < nfreq[active[m1]]) {
                    m2 = m1; m1 = i;
