    *extra_bits = 0; *extra_val = 0; return 257;
}

static int zl_dist_symbol(int dist, int *extra_bits, int *extra_val)
{
    int i;
    for (i = 29; i >= 0; i--) {
        if (zl_dist_base[i] <= dist) {
            *extra_bits = zl_dist_extra[i];
            *extra_val = dist - zl_dist_base[i];
            return i;
        }
    }
    *extra_bits = 0; *extra_val = 0; return 0;
}

static void zl_huffman_lengths(const unsigned *freq, int n, int maxbits,
                               unsigned char *lengths)
{
    int i, used = 0, only = -1;
    int *depth;
    memset(lengths, 0, (size_t)n);
    for (i = 0; i < n; i++)
        if (freq[i]) { used++; only = i; }
    if (used == 0)
        return;
    if (used == 1) {
        lengths[only] = 1;
        return;
    }
    {
        int max_nodes = 2 * n + 1;
        unsigned long long *nfreq = xmalloc(sizeof(*nfreq) * (size_t)max_nodes);
        int *parent = xmalloc(sizeof(*parent) * (size_t)max_nodes);
        int *symbol = xmalloc(sizeof(*symbol) * (size_t)max_nodes);
        int *active = xmalloc(sizeof(*active) * (size_t)max_nodes);
        int nn = 0, na = 0, root = -1;
        for (i = 0; i < n; i++) {
            if (freq[i]) {
                nfreq[nn] = freq[i];
                parent[nn] = -1;
                symbol[nn] = i;
                active[na++] = nn;
                nn++;
            }
        }
        while (na > 1) {
            int m1 = 0, m2 = 1, t;
            if (nfreq[active[m2]] < nfreq[active[m1]]) { t = m1; m1 = m2; m2 = t; }
            for (i = 2; i < na; i++) {
                if (nfreq[active[i]] < nfreq[active[m1]]) {
                    m2 = m1; m1 = i;
                } else if (nfreq[active[i]] < nfreq[active[m2]]) {
                    m2 = i;
                }
            }
            {
                int c1 = active[m1], c2 = active[m2];
                nfreq[nn] = nfreq[c1] + nfreq[c2];
                parent[nn] = -1;
                symbol[nn] = -1;
                parent[c1] = nn;
                parent[c2] = nn;
                root = nn;
                /* remove the higher list index first */
                active[m2] = active[--na];
                active[m1] = active[--na];
                active[na++] = nn;
                nn++;
            }
        }
        depth = xmalloc(sizeof(*depth) * (size_t)nn);
        for (i = 0; i < nn; i++) {
            int d = 0, p = i;
            while (parent[p] >= 0) { d++; p = parent[p]; }
            depth[i] = d;
        }
        (void)root;
        for (i = 0; i < nn; i++)
            if (symbol[i] >= 0)
                lengths[symbol[i]] = (unsigned char)depth[i];
        free(nfreq); free(parent); free(symbol); free(active); free(depth);
    }
    {
        int maxdepth = 0;
        for (i = 0; i < n; i++)
            if (lengths[i] > maxdepth) maxdepth = lengths[i];
        if (maxdepth > maxbits) {
            long kraft = 0, target = 1L << maxbits;
            for (i = 0; i < n; i++)
                if (lengths[i] > maxbits) lengths[i] = (unsigned char)maxbits;
            for (i = 0; i < n; i++)
                if (lengths[i]) kraft += 1L << (maxbits - lengths[i]);
            while (kraft > target) {
                int best = -1;
                for (i = 0; i < n; i++) {
                    if (lengths[i] && lengths[i] < maxbits) {
                        if (best < 0 || freq[i] < freq[best] ||
                            (freq[i] == freq[best] && lengths[i] > lengths[best]))
                            best = i;
                    }
                }
                if (best < 0) break;
                kraft -= 1L << (maxbits - lengths[best]);
                lengths[best]++;
                kraft += 1L << (maxbits - lengths[best]);
            }
            while (kraft < target) {
                int best = -1;
                long add;
                for (i = 0; i < n; i++) {
                    if (lengths[i] > 1) {
                        add = 1L << (maxbits - (lengths[i] - 1)) -
                              (1L << (maxbits - lengths[i]));
                        if (kraft + add <= target &&
                            (best < 0 || freq[i] > freq[best]))
                            best = i;
                    }
                }
                if (best < 0) break;
                kraft += 1L << (maxbits - (lengths[best] - 1)) -
                         (1L << (maxbits - lengths[best]));
                lengths[best]--;
            }
        }
    }
}

static void zl_build_codes(const unsigned char *lengths, int n,
                           unsigned *codes)
{
    unsigned count[32] = {0};
    unsigned next[32] = {0};
    int i, bits;
    for (i = 0; i < n; i++)
        if (lengths[i]) count[lengths[i]]++;
    for (bits = 1; bits < 32; bits++)
        next[bits] = (next[bits - 1] + count[bits - 1]) << 1;
    for (i = 0; i < n; i++) {
        codes[i] = 0;
        if (lengths[i])
            codes[i] = next[lengths[i]]++;
    }
}

typedef struct {
    int is_match;
    unsigned char lit;
    uint16_t len;
    uint16_t dist;
} ZSym;

typedef struct {
    ZSym *v;
    size_t n, cap;
} ZSeq;

static void zseq_push(ZSeq *s, ZSym sym)
{
    if (s->n == s->cap) {
        s->cap = s->cap ? s->cap * 2 : 256;
        s->v = xrealloc(s->v, s->cap * sizeof(*s->v));
    }
    s->v[s->n++] = sym;
}

static int zseq_equal(const ZSeq *a, const ZSeq *b)
{
    size_t i;
    if (a->n != b->n) return 0;
    for (i = 0; i < a->n; i++) {
        if (a->v[i].is_match != b->v[i].is_match ||
            a->v[i].lit != b->v[i].lit ||
            a->v[i].len != b->v[i].len ||
            a->v[i].dist != b->v[i].dist)
            return 0;
    }
    return 1;
}

static void zl_count_freq(const ZSeq *seq, unsigned *litfreq,
                          unsigned *distfreq)
{
    size_t i;
    memset(litfreq, 0, sizeof(unsigned) * 288);
    memset(distfreq, 0, sizeof(unsigned) * 30);
    for (i = 0; i < seq->n; i++) {
        if (!seq->v[i].is_match) {
            litfreq[seq->v[i].lit]++;
        } else {
            int eb, ev, ds, deb, dev;
            ds = zl_length_symbol(seq->v[i].len, &eb, &ev);
            litfreq[ds]++;
            ds = zl_dist_symbol(seq->v[i].dist, &deb, &dev);
            distfreq[ds]++;
        }
    }
    litfreq[256]++;
}

typedef struct {
    int hlit, hdist, hclen;
    unsigned char litlen[288];
    unsigned char distlen[30];
    unsigned char cllen[19];
    int *opsym;
    int *opextra;
    int *opextrabits;
    size_t nops, opscap;
} DynPlan;

static void dynplan_free(DynPlan *p)
{
    free(p->opsym); free(p->opextra); free(p->opextrabits);
}

static void dyn_add_op(DynPlan *p, int sym, int extra, int extrabits)
{
    if (p->nops == p->opscap) {
        p->opscap = p->opscap ? p->opscap * 2 : 128;
        p->opsym = xrealloc(p->opsym, p->opscap * sizeof(int));
        p->opextra = xrealloc(p->opextra, p->opscap * sizeof(int));
        p->opextrabits = xrealloc(p->opextrabits, p->opscap * sizeof(int));
    }
    p->opsym[p->nops] = sym;
    p->opextra[p->nops] = extra;
    p->opextrabits[p->nops] = extrabits;
    p->nops++;
}

/* Build a dynamic-block header plan.  Returns header size in bits. */
static long zl_dynamic_plan(const unsigned char *litlen_in,
                            const unsigned char *distlen_in, DynPlan *p)
{
    unsigned char seq[318];
    unsigned clfreq[19] = {0};
    int i, seqlen;
    long bits;
    memset(p, 0, sizeof(*p));
    memcpy(p->litlen, litlen_in, 288);
    memcpy(p->distlen, distlen_in, 30);
    /* Guarantee at least two distance codes when exactly one is used. */
    {
        int used = 0, usedsym = -1;
        for (i = 0; i < 30; i++)
            if (p->distlen[i]) { used++; usedsym = i; }
        if (used == 1) {
            int add = usedsym == 0 ? 1 : 0;
            p->distlen[add] = p->distlen[usedsym];
        }
        if (used == 0)
            p->distlen[0] = 1;
    }
    p->hlit = 287;
    while (p->hlit > 257 && p->litlen[p->hlit - 1] == 0) p->hlit--;
    p->hdist = 30;
    while (p->hdist > 1 && p->distlen[p->hdist - 1] == 0) p->hdist--;
    for (i = 0; i < p->hlit; i++) seq[i] = p->litlen[i];
    for (i = 0; i < p->hdist; i++) seq[p->hlit + i] = p->distlen[i];
    seqlen = p->hlit + p->hdist;
    i = 0;
    while (i < seqlen) {
        int val = seq[i];
        int run = 1, rem;
        while (i + run < seqlen && seq[i + run] == val) run++;
        dyn_add_op(p, val, 0, 0);
        rem = run - 1;
        if (val == 0) {
            while (rem >= 11) {
                int take = rem > 138 ? 138 : rem;
                if (rem - take > 0 && rem - take < 3) take = rem - 3;
                dyn_add_op(p, 18, take - 11, 7);
                rem -= take;
            }
            while (rem >= 3) {
                int take = rem > 10 ? 10 : rem;
                dyn_add_op(p, 17, take - 3, 3);
                rem -= take;
            }
            while (rem > 0) { dyn_add_op(p, 0, 0, 0); rem--; }
        } else {
            while (rem >= 3) {
                int take = rem > 6 ? 6 : rem;
                dyn_add_op(p, 16, take - 3, 2);
                rem -= take;
            }
            while (rem > 0) { dyn_add_op(p, val, 0, 0); rem--; }
        }
        i += run;
    }
    for (i = 0; (size_t)i < p->nops; i++)
        clfreq[p->opsym[i]]++;
    zl_huffman_lengths(clfreq, 19, 7, p->cllen);
    for (i = 0; (size_t)i < p->nops; i++)
        if (p->cllen[p->opsym[i]] == 0 && clfreq[p->opsym[i]] > 0)
            return -1;
    {
        static const int order[19] = {16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15};
        p->hclen = 19;
        while (p->hclen > 4 && p->cllen[order[p->hclen - 1]] == 0) p->hclen--;
        bits = 5 + 5 + 4 + (long)p->hclen * 3;
        for (i = 0; (size_t)i < p->nops; i++)
            bits += p->cllen[p->opsym[i]] + p->opextrabits[i];
    }
    return bits;
}

